<script setup lang="ts">
import IndexRuntimePanel from '~/components/indexing/IndexRuntimePanel.vue'
import { hierarchyOrder, hierarchyDepth, descendants, validateHierarchy } from '~/utils/indexHierarchy'
import { calculate } from '~/utils/indexFieldRuntime'
import type { CurrentUserResponse } from '~/types/auth'
import type { AdminContentStudioOverview,AdminFieldCatalogItem,AdminIndexField,AdminIndexFormDetail } from '~/types/admin-content-studio'
import type { AdminRuntimeOverview,AdminRuntimeTaxonomy,AdminRuntimeTerm,AdminRuntimeTermsResponse,RuntimeContentTypeCode } from '~/types/admin-runtime-index'
import type { IndexFieldDefinition,IndexSchema } from '~/composables/useIndexRuntime'
import type { IndexPayload } from '~/types/content'

useHead({title:'نمایه‌ساز حرفه‌ای'})
const route=useRoute(),router=useRouter(),auth=useZohaAuth(),studio=useAdminContentStudio(),runtime=useAdminRuntimeIndex()
const user=ref<CurrentUserResponse|null>(null)
const studioData=ref<AdminContentStudioOverview|null>(null),runtimeData=ref<AdminRuntimeOverview|null>(null),form=ref<AdminIndexFormDetail|null>(null)
const selectedType=ref<RuntimeContentTypeCode>('mold'),selectedFieldId=ref('')
const sideTab=ref<'elements'|'settings'>('elements'),sideCollapsed=ref(false),elementSearch=ref(''),dragIndex=ref<number|null>(null)
const mode=ref<'design'|'preview'>('design'),loading=ref(true),busy=ref(false),errorMessage=ref(''),previewKey=ref(0)
const previewPayload=ref<IndexPayload>({topicAnalyses:[]})
const paletteDrag=ref(''),collapsedGroups=reactive<Record<string,boolean>>({}),previewDevice=ref('desktop'),settingsSnapshot=ref(''),optionBulk=ref('')
const advanced=reactive({DefaultValue:'',Min:'',Max:'',MinLength:'',MaxLength:'',Pattern:'',ValidationMessage:'',Rows:4,Step:1,MaxRows:20,Accept:'.pdf,.jpg,.jpeg,.png,.docx',MaxFileMB:1,MaxFiles:5,Multiple:false,Stars:5,Formula:'',Price:0,Currency:'تومان',QuantityField:'',Columns:[{key:'value',label:'مقدار'}],OptionImages:{} as Record<string,string>,OptionPrices:{} as Record<string,number>,ConditionMatch:'all',ConditionRules:[] as {fieldKey:string;operator:string;value:string}[]})
const settingsDirty=computed(()=>Boolean(selectedField.value)&&settingsSnapshot.value!==JSON.stringify({fieldForm,advanced}))
const canLeaveSettings=()=>!settingsDirty.value||confirm('تنظیمات ذخیره‌نشده کنار گذاشته شوند؟')
const icons:Record<string,string>={text:'T',textarea:'¶',richtext:'B',number:'#',boolean:'✓',email:'@',phone:'☎',url:'↗',date:'▦',time:'◷',datetime:'▦',password:'⚿',select:'⌄',searchable_select:'⌕',multiselect:'☷',radio:'◉',checkbox:'☑',tags:'⌗',consent:'✓',file:'↑',reference:'↗',relation:'⇄',repeater:'≡',group:'▣',duration:'◷',color:'◈',range:'↔',name:'♙',address:'⌂',section:'§',html:'‹/›',page:'▤',hidden:'◌',image_choice:'▧',list:'▦',rating:'★',signature:'✎',calculation:'ƒ',product:'◈',quantity:'×',price_option:'±',shipping:'⇢',total:'∑'}

const termOpen=ref(false),termBusy=ref(false),termSearch=ref(''),termIncludeInactive=ref(false),termPage=ref(1),termData=ref<AdminRuntimeTermsResponse|null>(null)
const editingTermId=ref<string|null>(null),parentSearch=ref(''),parentCandidates=ref<AdminRuntimeTerm[]>([])
const termForm=reactive({Title:'',ParentHint:'',ParentId:'',SortOrder:0,IsActive:true})

const fieldForm=reactive({
 Key:'',Label:'',InputKind:'text',ValueKind:'string',HelpText:'',Placeholder:'',Width:100,Required:false,SearchEnabled:true,IndexEnabled:true,
 SourceMode:'none',TaxonomyCode:'',ParentKey:'',AllowsPersonal:false,Html:'',
 ConditionEnabled:false,ConditionField:'',ConditionOperator:'equals',ConditionValue:'',ConditionAction:'show',
 Options:[] as {Label:string;Value:string}[],
})

const initialType=():RuntimeContentTypeCode=>{const q=String(route.query.contentType??'');return ['mold','full_sermon','supporting'].includes(q)?q as RuntimeContentTypeCode:'mold'}
const fa=(v:number)=>new Intl.NumberFormat('fa-IR').format(v)
const selectedField=computed(()=>form.value?.Fields.find(v=>v.Id===selectedFieldId.value)??null)
const selectedTypeInfo=computed(()=>runtimeData.value?.ContentTypes.find(v=>v.Code===selectedType.value)??null)
const treeNodes=computed(()=>(form.value?.Fields??[]).map(f=>({key:f.Key,parentKey:String((f.Config?.hierarchy as Record<string,unknown>|undefined)?.parentKey??'')||null,field:f})))
const designFields=computed(()=>{try{return hierarchyOrder(treeNodes.value).map(n=>n.field)}catch{return form.value?.Fields??[]}})
const fieldDepth=(f:AdminIndexField)=>{try{return hierarchyDepth(treeNodes.value,f.Key)}catch{return 0}}
const parentKeyFor=(f:AdminIndexField)=>String((f.Config?.hierarchy as Record<string,unknown>|undefined)?.parentKey??'')
const parentFieldFor=(f:AdminIndexField)=>form.value?.Fields.find(p=>p.Key===parentKeyFor(f))??null
const pathFor=(f:AdminIndexField):string=>{const chain:string[]=[];const seen=new Set<string>();let node:AdminIndexField|null=f;while(node&&!seen.has(node.Key)){seen.add(node.Key);chain.unshift(node.Label);node=parentFieldFor(node)}return chain.join(' / ')}
const parentCandidatesForField=computed(()=>{const f=selectedField.value;if(!f)return [];const blocked=new Set([f.Key,...descendants(treeNodes.value,f.Key)]);return designFields.value.filter(p=>!blocked.has(p.Key)&&fieldDepth(p)<3&&!['page','html','hidden'].includes(p.InputKind))})
const selectedTaxonomy=computed<AdminRuntimeTaxonomy|null>(()=>{const f=selectedField.value;if(!f||!fieldForm.TaxonomyCode)return null;const parent=form.value?.Fields.find(p=>p.Key===fieldForm.ParentKey);return {Code:fieldForm.TaxonomyCode,Title:fieldForm.Label,LegacyTitle:null,FieldType:fieldForm.InputKind,IsMulti:['multiselect','tags','checkbox'].includes(fieldForm.InputKind),AllowsPersonal:fieldForm.AllowsPersonal,Metadata:{},IsActive:true,ActiveTermCount:0,TotalTermCount:0,Assigned:true,SortOrder:f.DisplayOrder,IsRequired:fieldForm.Required,Settings:{},ParentTaxonomyCode:parent?fieldTaxonomyCode(parent)||null:null}})
const sourceCapable=computed(()=>['select','searchable_select','multiselect','radio','checkbox','tags','image_choice','price_option'].includes(fieldForm.InputKind))
const manualOptionsEnabled=computed(()=>sourceCapable.value&&fieldForm.SourceMode==='manual')
watch(()=>fieldForm.InputKind,kind=>{if(kind!==selectedField.value?.InputKind){const item=studioData.value?.FieldCatalog.find(x=>x.Kind===kind);if(item)fieldForm.ValueKind=item.ValueKind;if(['image_choice','price_option'].includes(kind))fieldForm.SourceMode='manual'}})
const paletteGroups=computed(()=>{
 const q=elementSearch.value.trim().toLocaleLowerCase('fa-IR')
 const rows=(studioData.value?.FieldCatalog??[]).filter(x=>!q||x.Title.toLocaleLowerCase('fa-IR').includes(q)||x.Kind.includes(q))
 const groups=new Map<string,AdminFieldCatalogItem[]>()
 for(const row of rows){const list=groups.get(row.Group)??[];list.push(row);groups.set(row.Group,list)}
 return [...groups.entries()].map(([name,items])=>({name,items}))
})
const fieldKindTitle=(kind:string)=>studioData.value?.FieldCatalog.find(x=>x.Kind===kind)?.Title??kind
const taxonomyTitle=(code:string)=>form.value?.Fields.find(x=>fieldTaxonomyCode(x)===code)?.Label??code
const fieldTaxonomyCode=(f:AdminIndexField):string=>{const runtimeCfg=(f.Config?.runtime&&typeof f.Config.runtime==='object'&&!Array.isArray(f.Config.runtime)?f.Config.runtime:{}) as Record<string,unknown>;return String(runtimeCfg.taxonomyCode??'')}


const syncFieldForm=()=>{
 const f=selectedField.value
 if(!f){Object.assign(fieldForm,{Key:'',Label:'',InputKind:'text',ValueKind:'string',HelpText:'',Placeholder:'',Width:100,Required:false,SearchEnabled:true,IndexEnabled:true,SourceMode:'none',TaxonomyCode:'',ParentKey:'',AllowsPersonal:false,Html:'',ConditionEnabled:false,ConditionField:'',ConditionOperator:'equals',ConditionValue:'',ConditionAction:'show',Options:[]});return}
 const runtimeCfg=(f.Config?.runtime&&typeof f.Config.runtime==='object'&&!Array.isArray(f.Config.runtime)?f.Config.runtime:{}) as Record<string,unknown>
 const condition=(f.Config?.condition&&typeof f.Config.condition==='object'&&!Array.isArray(f.Config.condition)?f.Config.condition:{}) as Record<string,unknown>
 Object.assign(fieldForm,{
  Key:f.Key,Label:f.Label,InputKind:f.InputKind,ValueKind:f.ValueKind,HelpText:f.HelpText??'',Placeholder:f.Placeholder??'',Width:f.Width,Required:f.Required,
  SearchEnabled:f.SearchEnabled,IndexEnabled:f.IndexEnabled,SourceMode:String(runtimeCfg.sourceMode??(f.Options.length?'manual':'none')),TaxonomyCode:String(runtimeCfg.taxonomyCode??''),ParentKey:parentKeyFor(f),AllowsPersonal:Boolean(runtimeCfg.allowsPersonal),Html:String(f.Config?.html??''),
  ConditionEnabled:Boolean(condition.enabled),ConditionField:String(condition.fieldKey??''),ConditionOperator:String(condition.operator??'equals'),ConditionValue:String(condition.value??''),ConditionAction:String(condition.action??'show'),
  Options:f.Options.map(x=>({Label:x.Label,Value:x.Value})),
 })
 const c=f.Config??{},v=f.Validation??{}
 Object.assign(advanced,{DefaultValue:String(c.defaultValue??''),Min:String(v.min??''),Max:String(v.max??''),MinLength:String(v.minLength??''),MaxLength:String(v.maxLength??''),Pattern:String(v.pattern??''),ValidationMessage:String(v.message??''),Rows:Number(c.rows??4),Step:Number(c.step??1),MaxRows:Number(c.maxRows??20),Accept:String(c.accept??'.pdf,.jpg,.jpeg,.png,.docx'),MaxFileMB:Number(c.maxFileMB??1),MaxFiles:Number(c.maxFiles??5),Multiple:Boolean(c.multiple),Stars:Number(c.stars??5),Formula:String(c.formula??''),Price:Number(c.price??0),Currency:String(c.currency??'تومان'),QuantityField:String(c.quantityField??''),Columns:JSON.parse(JSON.stringify(c.columns??[{key:'value',label:'مقدار'}])),OptionImages:{...c.optionImages as Record<string,string>??{}},OptionPrices:{...c.optionPrices as Record<string,number>??{}},ConditionMatch:String(condition.match??'all'),ConditionRules:JSON.parse(JSON.stringify(condition.rules??[]))})
 settingsSnapshot.value=JSON.stringify({fieldForm,advanced})
}
watch(selectedFieldId,syncFieldForm)

const load=async(type:RuntimeContentTypeCode=selectedType.value)=>{
 loading.value=true;errorMessage.value=''
 try{
  if(!user.value){user.value=await auth.me();if(!user.value?.roles?.includes('system_admin')){await navigateTo('/welcome');return}}
  selectedType.value=type
  const s=await studio.overview()
  studioData.value=s;runtimeData.value={SelectedContentType:type,ContentTypes:s.ContentTypes.filter(c=>['mold','full_sermon','supporting'].includes(c.Code)).map(c=>({Code:c.Code as RuntimeContentTypeCode,Title:c.Title,Description:c.Description,Settings:c.Settings,FieldCount:0,RuntimeEnabled:true})),Taxonomies:[],Fields:[],Relations:[]}
  const ct=s.ContentTypes.find(x=>x.Code===type)
  if(!ct?.IndexFormId)throw new Error('برای این نوع محتوا فرم نمایه اصلی تعیین نشده است.')
  form.value=await studio.getIndexForm(ct.IndexFormId)
  if(!selectedFieldId.value||!form.value.Fields.some(x=>x.Id===selectedFieldId.value))selectedFieldId.value=form.value.Fields[0]?.Id??''
  syncFieldForm();previewKey.value+=1
 }catch(e:unknown){errorMessage.value=e instanceof Error?e.message:'نمایه‌ساز حرفه‌ای بارگذاری نشد.'}
 finally{loading.value=false}
}
onMounted(()=>void load(initialType()))

const changeType=async(type:RuntimeContentTypeCode)=>{if(busy.value||!canLeaveSettings())return;selectedFieldId.value='';sideTab.value='elements';mode.value='design';await router.replace({query:{...route.query,contentType:type}});await load(type)}
const selectField=(id:string)=>{if(busy.value||selectedFieldId.value!==id&&!canLeaveSettings())return;selectedFieldId.value=id;sideTab.value='settings';syncFieldForm()}
const uniqueKey=(kind:string)=>`field_${kind.replace(/[^a-z0-9_]/g,'_')}_${Date.now().toString(36)}`
const addElement=async(item:AdminFieldCatalogItem,index?:number,parentKey='')=>{
 if(!form.value||busy.value||!canLeaveSettings())return

 busy.value=true;errorMessage.value=''
 try{
  const addedKey=uniqueKey(item.Kind)
  const choices=['select','searchable_select','multiselect','radio','checkbox','image_choice','price_option'].includes(item.Kind)
  form.value=await studio.addField(form.value.Id,{Key:addedKey,Label:item.Title,InputKind:item.Kind,ValueKind:item.ValueKind,Required:false,SearchEnabled:true,IndexEnabled:!['section','html','page'].includes(item.Kind),Width:100,Config:{runtime:{sourceMode:choices&&!['image_choice','price_option'].includes(item.Kind)?'runtime_taxonomy':choices?'manual':'none',allowsPersonal:false},hierarchy:{parentKey:parentKey||null},authority:'index-builder',columns:[{key:'value',label:'مقدار'}]},Validation:{},Options:choices&&['image_choice','price_option'].includes(item.Kind)?[{Label:'گزینه اول',Value:'option_1'},{Label:'گزینه دوم',Value:'option_2'}]:[]})
  const added=form.value.Fields.find(f=>f.Key===addedKey);selectedFieldId.value=added?.Id??''
  if(index!==undefined&&added){const ordered=form.value.Fields.filter(f=>f.Id!==added.Id);ordered.splice(index,0,added);form.value=await studio.reorder(form.value.Id,ordered.map(f=>f.Id))}
  sideTab.value='settings';syncFieldForm();previewKey.value+=1
 }catch(e:unknown){errorMessage.value=e instanceof Error?e.message:'افزودن المنت انجام نشد.'}
 finally{busy.value=false}
}
const buildConfig=()=>{
 const current=selectedField.value?.Config??{}
 const parent=form.value?.Fields.find(f=>f.Key===fieldForm.ParentKey)
 return {...current,defaultValue:advanced.DefaultValue,rows:advanced.Rows,step:advanced.Step,maxRows:advanced.MaxRows,accept:advanced.Accept,maxFileMB:advanced.MaxFileMB,maxFiles:advanced.MaxFiles,multiple:advanced.Multiple,stars:advanced.Stars,formula:advanced.Formula,price:advanced.Price,currency:advanced.Currency,quantityField:advanced.QuantityField,columns:advanced.Columns,optionImages:advanced.OptionImages,optionPrices:advanced.OptionPrices,html:fieldForm.Html,authority:'index-builder',hierarchy:{parentKey:fieldForm.ParentKey||null},runtime:{sourceMode:sourceCapable.value?fieldForm.SourceMode:'none',taxonomyCode:fieldForm.TaxonomyCode||null,allowsPersonal:fieldForm.AllowsPersonal,parentTaxonomyCode:parent?fieldTaxonomyCode(parent)||null:null},condition:{enabled:fieldForm.ConditionEnabled,fieldKey:fieldForm.ConditionField||null,operator:fieldForm.ConditionOperator,value:fieldForm.ConditionValue,action:fieldForm.ConditionAction,match:advanced.ConditionMatch,rules:[{fieldKey:fieldForm.ConditionField,operator:fieldForm.ConditionOperator,value:fieldForm.ConditionValue},...advanced.ConditionRules]}}
}
const buildValidation=()=>{const v:Record<string,unknown>={};for(const [key,value] of Object.entries({min:advanced.Min,max:advanced.Max,minLength:advanced.MinLength,maxLength:advanced.MaxLength}))if(value!=='')v[key]=Number(value);if(advanced.Pattern)v.pattern=advanced.Pattern;if(advanced.ValidationMessage)v.message=advanced.ValidationMessage;return v}
const saveSettings=async()=>{
 if(!form.value||!selectedField.value||!fieldForm.Key.trim()||!fieldForm.Label.trim())return false
 if(!/^[a-z][a-z0-9_]{1,119}$/.test(fieldForm.Key.trim())){errorMessage.value='کلید باید با حرف انگلیسی آغاز شود و فقط حرف کوچک، عدد و زیرخط داشته باشد.';return false}
 if(manualOptionsEnabled.value&&new Set(fieldForm.Options.map(o=>o.Value.trim())).size!==fieldForm.Options.length){errorMessage.value='مقدار گزینه‌ها باید یکتا باشد.';return false}
 if(advanced.Min!==''&&advanced.Max!==''&&Number(advanced.Min)>Number(advanced.Max)||advanced.MinLength!==''&&advanced.MaxLength!==''&&Number(advanced.MinLength)>Number(advanced.MaxLength)){errorMessage.value='حداقل نمی‌تواند از حداکثر بیشتر باشد.';return false}
 if(fieldForm.InputKind==='file'&&(advanced.MaxFileMB<=0||advanced.MaxFileMB>10||advanced.MaxFiles<1||advanced.MaxFiles>20)){errorMessage.value='اندازه فایل تا ۱۰ مگابایت و تعداد فایل از ۱ تا ۲۰ مجاز است.';return false}
 if(['group','list'].includes(fieldForm.InputKind)&&advanced.Columns.some(c=>!/^[a-z][a-z0-9_]*$/.test(c.key))){errorMessage.value='کلید ستون‌ها باید انگلیسی و بدون فاصله باشد.';return false}
 if(['group','list'].includes(fieldForm.InputKind)&&new Set(advanced.Columns.map(c=>c.key)).size!==advanced.Columns.length){errorMessage.value='کلید ستون‌ها باید یکتا باشد.';return false}
 try{validateHierarchy(treeNodes.value.map(n=>({key:n.key===selectedField.value!.Key?fieldForm.Key.trim():n.key,parentKey:n.key===selectedField.value!.Key?fieldForm.ParentKey||null:n.parentKey===selectedField.value!.Key?fieldForm.Key.trim():n.parentKey})))}catch(e){errorMessage.value=e instanceof Error?e.message:'ساختار درخت معتبر نیست.';return false}
 if(fieldForm.InputKind==='calculation'&&(calculate(advanced.Formula,()=>1)===null||advanced.Formula.includes(`{${fieldForm.Key}}`))){errorMessage.value='فرمول معتبر وارد کنید؛ ارجاع به خود فیلد مجاز نیست.';return false}
 if(advanced.Pattern){try{new RegExp(advanced.Pattern)}catch{errorMessage.value='الگوی اعتبارسنجی معتبر نیست.';return false}}
 busy.value=true;errorMessage.value=''
 try{
  form.value=await studio.updateField(form.value.Id,selectedField.value.Id,{Key:fieldForm.Key.trim().toLowerCase().replace(/[^a-z0-9_]/g,'_'),Label:fieldForm.Label.trim(),InputKind:fieldForm.InputKind,ValueKind:fieldForm.ValueKind,HelpText:fieldForm.HelpText.trim(),Placeholder:fieldForm.Placeholder.trim(),Required:fieldForm.Required,SearchEnabled:fieldForm.SearchEnabled,IndexEnabled:fieldForm.IndexEnabled,Width:Number(fieldForm.Width),Config:buildConfig(),Validation:buildValidation(),Options:manualOptionsEnabled.value?fieldForm.Options.map(x=>({Label:x.Label.trim(),Value:x.Value.trim()})).filter(x=>x.Label||x.Value):[]})
  syncFieldForm();previewKey.value+=1;return true
 }catch(e:unknown){errorMessage.value=e instanceof Error?e.message:'تنظیمات فیلد ذخیره نشد.';return false}
 finally{busy.value=false}
}
const removeSelected=async()=>{if(!form.value||!selectedField.value||!confirm(`المنت «${selectedField.value.Label}» حذف شود؟`))return;busy.value=true;try{form.value=await studio.removeField(form.value.Id,selectedField.value.Id);selectedFieldId.value=form.value.Fields[0]?.Id??'';sideTab.value='elements';previewKey.value+=1}catch(e:unknown){errorMessage.value=e instanceof Error?e.message:'حذف المنت انجام نشد.'}finally{busy.value=false}}
const addOption=()=>fieldForm.Options.push({Label:`گزینه ${fieldForm.Options.length+1}`,Value:`option_${fieldForm.Options.length+1}`})
const removeOption=(index:number)=>fieldForm.Options.splice(index,1)

const startPaletteDrag=(key:string,event:DragEvent)=>{paletteDrag.value=key;dragIndex.value=null;event.dataTransfer?.setData('text/plain',key);if(event.dataTransfer)event.dataTransfer.effectAllowed='copy'}
const drop=async(index:number)=>{
 if(!form.value||busy.value)return
 const key=paletteDrag.value;paletteDrag.value=''
 if(key){const item=studioData.value?.FieldCatalog.find(x=>x.Kind===key);if(item)await addElement(item,index);return}
 if(dragIndex.value===null||dragIndex.value===index)return
 const previous=form.value,fields=[...designFields.value],from=dragIndex.value;dragIndex.value=null
 const moved=fields[from];if(!moved)return
 const keys=new Set([moved.Key,...descendants(treeNodes.value,moved.Key)]);const block=fields.filter(f=>keys.has(f.Key));const target=fields[index]
 if(target&&keys.has(target.Key))return
 const rest=fields.filter(f=>!keys.has(f.Key));const to=target?rest.findIndex(f=>f.Id===target.Id):rest.length
 rest.splice(Math.max(0,to),0,...block);fields.splice(0,fields.length,...rest);busy.value=true
 try{form.value=await studio.reorder(previous.Id,fields.map(v=>v.Id));previewKey.value+=1}catch(e:unknown){form.value=previous;errorMessage.value=e instanceof Error?e.message:'ترتیب فیلدها ذخیره نشد.'}finally{busy.value=false}
}
const move=async(index:number,delta:number)=>{if(!form.value||busy.value)return;const field=designFields.value[index];if(!field)return;const siblings=designFields.value.filter(f=>parentKeyFor(f)===parentKeyFor(field));const target=siblings[siblings.findIndex(f=>f.Id===field.Id)+delta];if(!target)return;const keys=new Set([field.Key,...descendants(treeNodes.value,field.Key)]),block=designFields.value.filter(f=>keys.has(f.Key)),rest=designFields.value.filter(f=>!keys.has(f.Key));let to=rest.findIndex(f=>f.Id===target.Id);if(delta>0){const targetKeys=new Set([target.Key,...descendants(treeNodes.value,target.Key)]);while(to<rest.length&&targetKeys.has(rest[to]!.Key))to++}rest.splice(to,0,...block);busy.value=true;try{form.value=await studio.reorder(form.value.Id,rest.map(f=>f.Id));previewKey.value++}catch(e){errorMessage.value=e instanceof Error?e.message:'جابه‌جایی انجام نشد.'}finally{busy.value=false}}
const publish=async()=>{if(!form.value||busy.value)return;if(settingsDirty.value&&!await saveSettings())return;if(!confirm('نسخه فعلی فرم منتشر شود؟ فرم منتشرشده بلافاصله مبنای نمایه‌زنی کاربران خواهد بود.'))return;busy.value=true;try{form.value=await studio.publish(form.value.Id);selectedFieldId.value=form.value.Fields.find(f=>f.Key===fieldForm.Key)?.Id??form.value.Fields[0]?.Id??'';syncFieldForm();previewKey.value+=1}catch(e:unknown){errorMessage.value=e instanceof Error?e.message:'انتشار فرم انجام نشد.'}finally{busy.value=false}}
const duplicateField=async(f:AdminIndexField)=>{if(!form.value||busy.value||!canLeaveSettings())return;busy.value=true;try{const copyKey=uniqueKey(f.InputKind);const cfg=JSON.parse(JSON.stringify(f.Config));if(cfg.runtime)cfg.runtime={...cfg.runtime,taxonomyCode:null,parentTaxonomyCode:null};form.value=await studio.addField(form.value.Id,{Key:copyKey,Label:f.Label+' (کپی)',InputKind:f.InputKind,ValueKind:f.ValueKind,HelpText:f.HelpText??'',Placeholder:f.Placeholder??'',Required:f.Required,SearchEnabled:f.SearchEnabled,IndexEnabled:f.IndexEnabled,Width:f.Width,Config:cfg,Validation:f.Validation,Options:f.Options});selectedFieldId.value=form.value.Fields.find(x=>x.Key===copyKey)?.Id??'';sideTab.value='settings';syncFieldForm();previewKey.value+=1}catch(e:unknown){errorMessage.value=e instanceof Error?e.message:'تکثیر انجام نشد.'}finally{busy.value=false}}
const applyBulkOptions=()=>{const rows=optionBulk.value.split(/\r?\n/).map(x=>x.trim()).filter(Boolean).map((line,i)=>{const [label,value]=line.split('|');return {Label:label!.trim(),Value:value?.trim()||`option_${i+1}`}});if(new Set(rows.map(x=>x.Value)).size!==rows.length){errorMessage.value='مقدار گزینه‌ها باید یکتا باشد.';return}fieldForm.Options=rows;optionBulk.value=''}
const addChild=async(f:AdminIndexField)=>{if(fieldDepth(f)>=3)return;const item=studioData.value?.FieldCatalog.find(x=>x.Kind==='searchable_select');if(item)await addElement({...item,Title:'زیرشاخه '+f.Label},undefined,f.Key)}
const reparentField=async(f:AdminIndexField,parentKey:string)=>{if(!canLeaveSettings())return;selectedFieldId.value=f.Id;syncFieldForm();fieldForm.ParentKey=parentKey;sideTab.value='settings';await saveSettings()}
const indentField=async(f:AdminIndexField,i:number)=>{const previous=designFields.value[i-1];if(previous)await reparentField(f,previous.Key)}
const outdentField=async(f:AdminIndexField)=>{const parent=parentFieldFor(f);await reparentField(f,parent?parentKeyFor(parent):'')}
const manageOwnItems=async()=>{if(settingsDirty.value&&!await saveSettings())return;await openTerms()}
const previewDraft=async()=>{if(settingsDirty.value&&!await saveSettings())return;mode.value='preview'}

const previewSchema=computed<IndexSchema|null>(()=>{
 if(!form.value||!runtimeData.value)return null
 const fields:IndexFieldDefinition[]=designFields.value.map(f=>{
  const runtimeCfg=(f.Config?.runtime&&typeof f.Config.runtime==='object'&&!Array.isArray(f.Config.runtime)?f.Config.runtime:{}) as Record<string,unknown>
  const taxonomyCode=String(runtimeCfg.taxonomyCode??'')||null
  const taxonomy=taxonomyCode?runtimeData.value?.Taxonomies.find(x=>x.Code===taxonomyCode):null
  const sourceMode=String(runtimeCfg.sourceMode??(f.Options.length?'manual':'none'))
  return {code:taxonomyCode??f.Key,key:f.Key,title:f.Label,type:f.InputKind,valueKind:f.ValueKind,multi:['multiselect','checkbox','tags'].includes(f.InputKind)||Boolean(taxonomy?.IsMulti),allowsPersonal:Boolean(runtimeCfg.allowsPersonal),sortOrder:f.DisplayOrder,required:f.Required,searchEnabled:f.SearchEnabled,indexEnabled:f.IndexEnabled,taxonomyCode,sourceMode,parentKey:parentKeyFor(f)||null,parentTaxonomyCode:parentFieldFor(f)?fieldTaxonomyCode(parentFieldFor(f)!)||null:null,legacyTitle:taxonomy?.LegacyTitle??null,settings:{helpText:f.HelpText??'',placeholder:f.Placeholder??'',width:f.Width},config:f.Config,validation:f.Validation,options:f.Options.map(x=>({value:x.Value,label:x.Label,sortOrder:x.SortOrder}))}
 })
 return {contentType:selectedType.value,version:6,builder:'index-builder-v6-draft-preview',fields,relations:runtimeData.value.Relations,topicAnalysis:{fields:['IDX-001','IDX-003','IDX-002','IDX-004'],label:'نمایه‌ها و زیرشاخه‌های تعریف‌شده در نمایه‌ساز'}}
})

const termTaxonomy=computed<AdminRuntimeTaxonomy|null>(()=>selectedTaxonomy.value??null)
const openTerms=async()=>{if(!termTaxonomy.value)return;termOpen.value=true;termSearch.value='';termPage.value=1;termIncludeInactive.value=false;editingTermId.value=null;Object.assign(termForm,{Title:'',ParentHint:'',ParentId:'',SortOrder:0,IsActive:true});parentSearch.value='';parentCandidates.value=[];await loadTerms()}
const loadTerms=async()=>{const t=termTaxonomy.value;if(!t)return;termBusy.value=true;try{termData.value=await runtime.terms(t.Code,termSearch.value,termPage.value,50,termIncludeInactive.value)}catch(e:unknown){errorMessage.value=e instanceof Error?e.message:'آیتم‌های نمایه دریافت نشد.'}finally{termBusy.value=false}}
let searchTimer:ReturnType<typeof setTimeout>|null=null
const queueTermSearch=()=>{if(searchTimer)clearTimeout(searchTimer);searchTimer=setTimeout(()=>{termPage.value=1;void loadTerms()},250)}
let parentTimer:ReturnType<typeof setTimeout>|null=null
const queueParentSearch=()=>{termForm.ParentId='';termForm.ParentHint='';const parentCode=termTaxonomy.value?.ParentTaxonomyCode;if(!parentCode)return;if(parentTimer)clearTimeout(parentTimer);parentTimer=setTimeout(async()=>{try{const r=await runtime.terms(parentCode,parentSearch.value,1,30,false);parentCandidates.value=r.Items}catch{parentCandidates.value=[]}},250)}
const chooseParent=(item:AdminRuntimeTerm)=>{termForm.ParentHint=item.Title;termForm.ParentId=item.Id;parentSearch.value=item.Title;parentCandidates.value=[]}
const editTerm=(item:AdminRuntimeTerm)=>{editingTermId.value=item.Id;Object.assign(termForm,{Title:item.Title,ParentHint:item.ParentHint??'',ParentId:item.ParentId??'',SortOrder:item.SortOrder,IsActive:item.IsActive});parentSearch.value=item.ParentHint??'';parentCandidates.value=[]}
const resetTerm=()=>{editingTermId.value=null;Object.assign(termForm,{Title:'',ParentHint:'',ParentId:'',SortOrder:0,IsActive:true});parentSearch.value='';parentCandidates.value=[]}
const saveTerm=async()=>{const t=termTaxonomy.value;if(!t||!termForm.Title.trim())return;termBusy.value=true;try{if(editingTermId.value)await runtime.updateTerm(t.Code,editingTermId.value,{Title:termForm.Title.trim(),ParentHint:termForm.ParentHint,ParentId:termForm.ParentId||undefined,SortOrder:Number(termForm.SortOrder),IsActive:termForm.IsActive});else await runtime.createTerm(t.Code,{Title:termForm.Title.trim(),ParentHint:termForm.ParentHint||undefined,ParentId:termForm.ParentId||undefined,SortOrder:Number(termForm.SortOrder)});resetTerm();await loadTerms();previewKey.value+=1}catch(e:unknown){errorMessage.value=e instanceof Error?e.message:'ذخیره آیتم انجام نشد.'}finally{termBusy.value=false}}
const deactivateTerm=async(item:AdminRuntimeTerm)=>{const t=termTaxonomy.value;if(!t||!confirm(`آیتم «${item.Title}» غیرفعال شود؟`))return;termBusy.value=true;try{await runtime.deleteTerm(t.Code,item.Id);await loadTerms();previewKey.value+=1}finally{termBusy.value=false}}
const reactivateTerm=async(item:AdminRuntimeTerm)=>{const t=termTaxonomy.value;if(!t)return;termBusy.value=true;try{await runtime.updateTerm(t.Code,item.Id,{IsActive:true});await loadTerms();previewKey.value+=1}finally{termBusy.value=false}}
</script>

<template>
<div class="admin-app">
 <AdminSidebar/>
 <main class="admin-main index-builder-main">
  <AdminHeader :user="user"/>
  <div class="admin-content builder-page">
   <header class="builder-head">
    <div><span>طراحی فرم و نمایه‌گذاری</span><h1>نمایه‌ساز حرفه‌ای ضحی</h1><p>با ابزارهای سمت چپ فرم بسازید، پیش‌نمایش را ببینید و نسخه نهایی را منتشر کنید.</p></div>
    <div class="head-actions"><NuxtLink to="/admin/content-types">انواع محتوا</NuxtLink><button :disabled="busy||!form" @click="publish">انتشار نسخه {{form?.DraftVersion??''}}</button></div>
   </header>

   <div v-if="loading" class="builder-loading">در حال بارگذاری نمایه‌ساز…</div>
   <template v-else>
    <div v-if="errorMessage" class="builder-error"><span>{{errorMessage}}</span><button @click="errorMessage=''">×</button></div>
    <nav class="content-switcher">
     <button v-for="item in runtimeData?.ContentTypes" :key="item.Code" :class="{active:selectedType===item.Code}" @click="changeType(item.Code)"><b>{{item.Title}}</b><small>{{item.Code===selectedType?fa(form?.Fields.length??0):''}} نمایه تعریف‌شده</small></button>
    </nav>

    <div class="builder-shell" :class="{collapsed:sideCollapsed}">
     <aside class="builder-tools">
      <div class="tool-top">
       <button class="collapse-btn" @click="sideCollapsed=!sideCollapsed"><span>{{sideCollapsed?'›':'‹'}}</span><b>{{sideCollapsed?'باز کردن':'جمع کردن ابزارها'}}</b></button>
       <div class="tool-tabs"><button :class="{active:sideTab==='elements'}" @click="sideTab='elements'"><span>＋</span><b>المنت‌ها</b></button><button :class="{active:sideTab==='settings'}" @click="sideTab='settings'"><span>⚙</span><b>تنظیمات</b></button></div>
      </div>

      <template v-if="!sideCollapsed&&sideTab==='elements'">
       <div class="tool-section-head"><div><h2>Toolbox فرم</h2><small>{{fa(studioData?.FieldCatalog.length??0)}} ابزار · کلیک یا کشیدن به بوم</small></div></div>
       <label class="tool-search"><span>⌕</span><input v-model="elementSearch" type="search" placeholder="جستجوی المنت…"></label>
       <div class="field-palette">
        <section v-for="group in paletteGroups" :key="group.name"><button class="group-toggle" @click="collapsedGroups[group.name]=!collapsedGroups[group.name]"><b>{{group.name}}</b><span>{{group.items.length}} {{collapsedGroups[group.name]?'＋':'−'}}</span></button><div v-show="!collapsedGroups[group.name]" class="palette-grid"><button v-for="item in group.items" :key="item.Kind" :disabled="busy" draggable="true" @dragstart="startPaletteDrag(item.Kind,$event)" @dragend="paletteDrag=''" @click="addElement(item)"><span>{{icons[item.Kind]||'◆'}}</span><b>{{item.Title}}</b><small>کلیک یا کشیدن به بوم</small></button></div></section>

        <div v-if="!paletteGroups.length" class="settings-empty">ابزاری پیدا نشد.</div>
       </div>
      </template>

      <template v-else-if="!sideCollapsed&&sideTab==='settings'">
       <div v-if="!selectedField" class="settings-empty">برای ویرایش تنظیمات، یک المنت را از بوم انتخاب کنید.</div>
       <div v-else class="settings-scroll">
        <div class="tool-section-head"><div><h2>{{selectedField.Label}}</h2><small>{{fieldKindTitle(selectedField.InputKind)}}</small></div><button class="danger-text" @click="removeSelected">حذف</button></div>
        <section class="settings-card"><h3>مشخصات فیلد</h3><label>کلید<input v-model="fieldForm.Key" dir="ltr"></label><label>عنوان<input v-model="fieldForm.Label"></label><label>نوع المنت<select v-model="fieldForm.InputKind"><option v-for="x in studioData?.FieldCatalog" :key="x.Kind" :value="x.Kind">{{x.Title}}</option></select></label><label>نوع مقدار<select v-model="fieldForm.ValueKind"><option v-for="x in ['string','number','boolean','date','object','array','reference']" :key="x" :value="x">{{x}}</option></select></label><label>راهنما<textarea v-model="fieldForm.HelpText"/></label><label>متن راهنمای ورودی<input v-model="fieldForm.Placeholder"></label><div class="two"><label>عرض<select v-model.number="fieldForm.Width"><option :value="25">۲۵٪</option><option :value="50">۵۰٪</option><option :value="75">۷۵٪</option><option :value="100">۱۰۰٪</option></select></label><label class="check"><input v-model="fieldForm.Required" type="checkbox"> الزامی</label></div><label class="check"><input v-model="fieldForm.SearchEnabled" type="checkbox"> قابل جستجو</label><label class="check"><input v-model="fieldForm.IndexEnabled" type="checkbox"> قابل نمایه‌سازی</label></section>

        <section class="settings-card hierarchy-settings"><h3>جایگاه درختی نمایه</h3><p>این نمایه در همین نمایه‌ساز تعریف می‌شود؛ فرم‌ها و بخش‌های سایت نسخه منتشرشده را می‌خوانند.</p><label>نمایه والد<select v-model="fieldForm.ParentKey" aria-label="نمایه والد"><option value="">نمایه اصلی (بدون والد)</option><option v-for="p in parentCandidatesForField" :key="p.Key" :value="p.Key">{{'— '.repeat(fieldDepth(p))}}{{p.Label}}</option></select></label><p v-if="fieldForm.ParentKey">ذیل «{{form?.Fields.find(f=>f.Key===fieldForm.ParentKey)?.Label}}» · سطح زیرشاخه {{(form?.Fields.find(f=>f.Key===fieldForm.ParentKey)?fieldDepth(form!.Fields.find(f=>f.Key===fieldForm.ParentKey)!):0)+1}} از ۳</p><p v-else>نمایه اصلی · تا سه سطح زیرشاخه</p><small>{{selectedField?pathFor(selectedField):''}}</small><button :disabled="busy||fieldDepth(selectedField)>=3" @click="addChild(selectedField)">+ افزودن زیرشاخه</button></section>
        <section v-if="sourceCapable" class="settings-card"><h3>آیتم‌های همین نمایه</h3><p>فهرست آیتم‌ها متعلق به این نمایه است و در بخش‌های سایت استفاده می‌شود.</p><label>شیوه تعریف گزینه‌ها<select v-model="fieldForm.SourceMode"><option value="manual">گزینه‌های دستی همین فرم</option><option value="runtime_taxonomy" :disabled="['image_choice','price_option'].includes(fieldForm.InputKind)">فهرست قابل جستجوی همین نمایه</option></select></label><label v-if="fieldForm.SourceMode==='runtime_taxonomy'" class="check"><input v-model="fieldForm.AllowsPersonal" type="checkbox"> کاربران بتوانند آیتم شخصی اضافه کنند</label><button v-if="fieldForm.SourceMode==='runtime_taxonomy'" class="manage-items" @click="manageOwnItems"><span>☷</span><div><b>مدیریت آیتم‌های این نمایه</b><small>جستجو، افزودن، ویرایش و غیرفعال‌سازی</small></div></button></section>

        <section v-if="manualOptionsEnabled" class="settings-card"><div class="setting-title"><h3>گزینه‌های دستی</h3><button @click="addOption">+ گزینه</button></div><div v-for="(o,i) in fieldForm.Options" :key="i" class="option-row"><input v-model="o.Label" placeholder="عنوان"><input v-model="o.Value" dir="ltr" placeholder="value"><button @click="removeOption(i)">×</button></div><p v-if="!fieldForm.Options.length">هنوز گزینه‌ای افزوده نشده است.</p></section>

        <section v-if="fieldForm.InputKind==='html'" class="settings-card"><h3>محتوای HTML</h3><textarea v-model="fieldForm.Html" rows="5" placeholder="HTML توضیحی…"/></section>

        <section class="settings-card"><h3>مقدار پیش‌فرض و اعتبارسنجی</h3><label>مقدار پیش‌فرض<input v-model="advanced.DefaultValue"></label><div class="two"><label>حداقل عدد<input v-model="advanced.Min" type="number"></label><label>حداکثر عدد<input v-model="advanced.Max" type="number"></label><label>حداقل نویسه<input v-model="advanced.MinLength" type="number" min="0"></label><label>حداکثر نویسه<input v-model="advanced.MaxLength" type="number" min="0"></label></div><label>الگوی مجاز (Regex)<input v-model="advanced.Pattern" dir="ltr" placeholder="^[0-9]+$"></label><label>پیام خطای الگو<input v-model="advanced.ValidationMessage"></label></section>
        <section v-if="['textarea','number','duration','range'].includes(fieldForm.InputKind)" class="settings-card"><h3>نمایش ورودی</h3><label v-if="fieldForm.InputKind==='textarea'">تعداد سطرها<input v-model.number="advanced.Rows" type="number" min="2" max="30"></label><label v-else>گام تغییر عدد<input v-model.number="advanced.Step" type="number" min="0.01" step="0.01"></label></section>
        <section v-if="fieldForm.InputKind==='file'" class="settings-card"><h3>بارگذاری فایل</h3><label>پسوند یا نوع مجاز<input v-model="advanced.Accept" dir="ltr" placeholder=".pdf,.jpg,.png"></label><div class="two"><label>حداکثر اندازه (MB)<input v-model.number="advanced.MaxFileMB" type="number" min="0.1" max="10" step="0.1"></label><label>حداکثر تعداد<input v-model.number="advanced.MaxFiles" type="number" min="1" max="20"></label></div><label class="check"><input v-model="advanced.Multiple" type="checkbox"> انتخاب چند فایل</label></section>
        <section v-if="['group','list','repeater'].includes(fieldForm.InputKind)" class="settings-card"><h3>فیلدهای ترکیبی</h3><label v-if="fieldForm.InputKind!=='group'">حداکثر ردیف<input v-model.number="advanced.MaxRows" type="number" min="1" max="100"></label><template v-if="fieldForm.InputKind!=='repeater'"><div v-for="(c,i) in advanced.Columns" :key="i" class="option-row"><input v-model="c.label" placeholder="عنوان ستون"><input v-model="c.key" dir="ltr" placeholder="key"><button :disabled="advanced.Columns.length===1" @click="advanced.Columns.splice(i,1)">×</button></div><button class="secondary" @click="advanced.Columns.push({key:'column_'+(advanced.Columns.length+1),label:'ستون جدید'})">+ افزودن ستون</button></template></section>
        <section v-if="fieldForm.InputKind==='rating'" class="settings-card"><h3>امتیازدهی</h3><label>تعداد ستاره<input v-model.number="advanced.Stars" type="number" min="2" max="10"></label></section>
        <section v-if="fieldForm.InputKind==='calculation'" class="settings-card"><h3>فرمول محاسبه</h3><textarea v-model="advanced.Formula" dir="ltr" placeholder="({field_price} * {field_count}) + 100"/><p>جمع، تفریق، ضرب، تقسیم و پرانتز؛ ارجاع به کلید فیلد در آکولاد.</p><div class="formula-fields"><button v-for="f in form?.Fields.filter(f=>f.Id!==selectedFieldId&&['number','quantity','duration','calculation'].includes(f.InputKind))" :key="f.Id" @click="advanced.Formula+='{'+f.Key+'}'">{{f.Label}}</button></div></section>
        <section v-if="['product','quantity','price_option','shipping','total'].includes(fieldForm.InputKind)" class="settings-card"><h3>تنظیمات مبلغ</h3><label>واحد پول<input v-model="advanced.Currency"></label><label v-if="['product','shipping'].includes(fieldForm.InputKind)">قیمت<input v-model.number="advanced.Price" type="number" min="0"></label><label v-if="fieldForm.InputKind==='product'">فیلد تعداد<select v-model="advanced.QuantityField"><option value="">ورودی تعداد داخل همین ابزار</option><option v-for="f in form?.Fields.filter(f=>f.Id!==selectedFieldId&&['number','quantity'].includes(f.InputKind))" :key="f.Id" :value="f.Key">{{f.Label}}</option></select></label><p v-if="fieldForm.InputKind==='total'">جمع قیمت محصولات، گزینه‌های قیمت و هزینه ارسال انتخاب‌شده.</p></section>
        <section v-if="manualOptionsEnabled" class="settings-card"><h3>ویرایش گروهی گزینه‌ها</h3><textarea v-model="optionBulk" rows="4" placeholder="هر سطر: عنوان | مقدار"/><button class="secondary" :disabled="!optionBulk.trim()" @click="applyBulkOptions">جایگزینی گزینه‌ها با این فهرست</button><template v-if="fieldForm.InputKind==='image_choice'"><h3>تصویر گزینه‌ها</h3><label v-for="o in fieldForm.Options" :key="o.Value">{{o.Label}}<input v-model="advanced.OptionImages[o.Value]" type="url" dir="ltr" placeholder="https://..."></label></template><template v-if="fieldForm.InputKind==='price_option'"><label v-for="o in fieldForm.Options" :key="o.Value">مبلغ {{o.Label}}<input v-model.number="advanced.OptionPrices[o.Value]" type="number" min="0"></label></template></section>
        <section class="settings-card"><h3>منطق شرطی</h3><label class="check"><input v-model="fieldForm.ConditionEnabled" type="checkbox"> فعال‌سازی شرط نمایش</label><template v-if="fieldForm.ConditionEnabled"><label>نوع تطبیق<select v-model="advanced.ConditionMatch"><option value="all">همه شرط‌ها</option><option value="any">حداقل یکی از شرط‌ها</option></select></label><label>فیلد مبنا<select v-model="fieldForm.ConditionField"><option value="">انتخاب فیلد</option><option v-for="x in form?.Fields.filter(x=>x.Id!==selectedFieldId)" :key="x.Id" :value="x.Key">{{x.Label}}</option></select></label><label>عملگر<select v-model="fieldForm.ConditionOperator"><option value="equals">برابر است</option><option value="not_equals">برابر نیست</option><option value="contains">شامل است</option><option value="not_contains">شامل نیست</option><option value="greater">بزرگ‌تر از</option><option value="less">کوچک‌تر از</option><option value="not_empty">خالی نیست</option><option value="empty">خالی است</option></select></label><label v-if="!['empty','not_empty'].includes(fieldForm.ConditionOperator)">مقدار<input v-model="fieldForm.ConditionValue"></label><div v-for="(rule,i) in advanced.ConditionRules" :key="i" class="condition-row"><select v-model="rule.fieldKey"><option v-for="f in form?.Fields.filter(f=>f.Id!==selectedFieldId)" :key="f.Id" :value="f.Key">{{f.Label}}</option></select><select v-model="rule.operator"><option value="equals">برابر</option><option value="not_equals">نابرابر</option><option value="contains">شامل</option><option value="not_empty">پر</option><option value="empty">خالی</option><option value="greater">بزرگ‌تر</option><option value="less">کوچک‌تر</option></select><input v-model="rule.value" placeholder="مقدار"><button @click="advanced.ConditionRules.splice(i,1)">×</button></div><button class="secondary" @click="advanced.ConditionRules.push({fieldKey:'',operator:'equals',value:''})">+ شرط دیگر</button><label>عمل<select v-model="fieldForm.ConditionAction"><option value="show">نمایش اگر شرط برقرار بود</option><option value="hide">مخفی اگر شرط برقرار بود</option></select></label></template></section>

        <div class="tool-footer"><small v-if="settingsDirty" class="unsaved">تغییرات ذخیره‌نشده دارید</small><button :disabled="busy||!settingsDirty" @click="saveSettings">{{busy?'در حال ذخیره…':settingsDirty?'ذخیره تغییرات':'تنظیمات ذخیره است'}}</button></div>
       </div>
      </template>
     </aside>

     <section class="builder-canvas">
      <header class="canvas-head"><div><span>{{selectedTypeInfo?.Title}}</span><h2>{{form?.Title}}</h2><p>نسخه منتشرشده {{form?.ActiveVersion}} · پیش‌نویس {{form?.DraftVersion}} · {{form?.Fields.length??0}} المنت</p></div><div class="mode-toggle"><button :class="{active:mode==='design'}" @click="mode='design'">طراحی</button><button :class="{active:mode==='preview'}" @click="previewDraft">نمایش واقعی کاربر</button></div></header>

      <div v-if="mode==='design'" class="canvas-fields" @dragover.prevent @drop.prevent.stop="drop(form?.Fields.length??0)">
       <article v-for="(f,i) in designFields" :key="f.Id" :class="{selected:selectedFieldId===f.Id}" draggable="true" :style="{gridColumn:'1 / -1',marginInlineStart:`${fieldDepth(f)*30}px`}" :data-depth="fieldDepth(f)" :data-field-key="f.Key" @dragstart.stop="dragIndex=i;paletteDrag=''" @dragend="dragIndex=null" @dragover.prevent @drop.prevent.stop="drop(i)" @click="selectField(f.Id)">
        <span class="drag">⋮⋮</span><div class="field-icon">{{f.InputKind==='text'?'T':f.InputKind==='textarea'?'¶':f.InputKind.includes('select')?'⌄':f.InputKind==='checkbox'?'☑':f.InputKind==='radio'?'◉':f.InputKind==='section'?'§':'◆'}}</div><div class="field-main"><div><b>{{f.Label}}</b><em>{{fieldKindTitle(f.InputKind)}}</em><em v-if="parentFieldFor(f)" class="runtime-badge">ذیل {{parentFieldFor(f)?.Label}} · سطح {{fieldDepth(f)}}</em><em v-else class="runtime-badge">نمایه اصلی</em></div><small class="tree-path">{{pathFor(f)}}</small><small>{{f.Key}} · عرض {{f.Width}}٪ <template v-if="f.Required">· الزامی</template></small></div><div class="move"><button :disabled="busy||fieldDepth(f)>=3" title="افزودن زیرشاخه" @click.stop="addChild(f)">＋</button><button :disabled="busy||i===0||fieldDepth(f)>=3" title="زیرشاخه نمایه قبلی" @click.stop="indentField(f,i)">↳</button><button :disabled="busy||!parentFieldFor(f)" title="یک سطح بالاتر" @click.stop="outdentField(f)">↰</button><button :disabled="busy" title="تکثیر فیلد" @click.stop="duplicateField(f)">⧉</button><button :disabled="busy||i===0" title="بالا" @click.stop="move(i,-1)">↑</button><button :disabled="busy||i===(form?.Fields.length??0)-1" title="پایین" @click.stop="move(i,1)">↓</button></div>
       </article>
       <div v-if="!form?.Fields.length" class="canvas-empty"><b>فرم خالی است</b><span>از Toolbox سمت چپ یک المنت اضافه کنید.</span></div>
      </div>

      <div v-else class="real-preview" :class="previewDevice"><div class="device-switch" aria-label="اندازه پیش‌نمایش"><button v-for="d in [{key:'desktop',title:'دسکتاپ'},{key:'tablet',title:'تبلت'},{key:'mobile',title:'موبایل'}]" :key="d.key" :class="{active:previewDevice===d.key}" @click="previewDevice=d.key">{{d.title}}</button></div><div class="preview-banner"><b>پیش‌نمایش پیش‌نویس</b><span>تغییرات پس از انتشار برای کاربران نمایش داده می‌شود.</span></div><IndexRuntimePanel v-if="previewSchema" :key="previewKey" :content-type="selectedType" :schema-override="previewSchema" :model-value="previewPayload" embedded :admin-preview="true" @update:model-value="previewPayload=$event"/></div>
     </section>
    </div>
   </template>
